<?php declare(strict_types=1);
if(!defined('ABSPATH')) exit;
/** The storefront uses a shared catalog and the lang query argument for EN. */
function ferreta_language():string{return isset($_GET['lang'])&&sanitize_key((string)$_GET['lang'])==='en'?'en':'uk';}
function ferreta_localized_url(string $url):string{return ferreta_language()==='en'?add_query_arg('lang','en',$url):$url;}
function ferreta_language_switcher():string{$current=home_url(wp_unslash($_SERVER['REQUEST_URI']??'/'));$uk=remove_query_arg('lang',$current);$en=add_query_arg('lang','en',$uk);return '<a class="'.(ferreta_language()==='uk'?'is-active':'').'" href="'.esc_url($uk).'">UA</a><a class="'.(ferreta_language()==='en'?'is-active':'').'" href="'.esc_url($en).'">EN</a>';}
add_filter('page_link',fn(string $url):string=>ferreta_localized_url($url),20);
add_filter('post_type_link',fn(string $url):string=>ferreta_localized_url($url),20);
add_filter('term_link',fn(string $url):string=>ferreta_localized_url($url),20);
add_filter('woocommerce_get_cart_url',fn(string $url):string=>ferreta_localized_url($url),20);
add_filter('woocommerce_get_checkout_url',fn(string $url):string=>ferreta_localized_url($url),20);
add_filter('language_attributes',fn(string $attributes):string=>ferreta_language()==='en'?'lang="en-US"':$attributes,20);
function ferreta_translate_markup(string $html):string{if(ferreta_language()!=='en')return $html;return strtr($html,['Предмети для дому, тераси та бізнесу'=>'Objects for home, terrace and business','B2B / Дизайнерам'=>'B2B / Designers','Запит на підбір'=>'Request a selection','Каталог'=>'Catalog','Категорії'=>'Categories','Проєкти'=>'Projects','Для бізнесу'=>'For business','Про бренд'=>'About','Кошик'=>'Cart','Пошук за назвою або SKU'=>'Search by name or SKU','Шукати'=>'Search','Декор, що надає'=>'Decor that gives','простору характер.'=>'your space character.','Виразні предмети для дому, тераси та бізнесу: світло, меблі, лофт-об’єкти й малі деталі, які хочеться розглядати.'=>'Expressive objects for home, terrace and business: lighting, furniture, loft objects and small details worth looking at.','Переглянути каталог'=>'Browse catalog','Підібрати декор для проєкту'=>'Select decor for a project','Простір запам’ятовується деталями.'=>'A space is remembered through its details.','ОБИРАЙТЕ ЗА КАТЕГОРІЄЮ'=>'SHOP BY CATEGORY','Один простір.'=>'One space.','Багато виразних деталей.'=>'Many expressive details.','Усі категорії декору'=>'All decor categories','Декоративне освітлення'=>'Decorative lighting','Меблі лофт'=>'Loft furniture','Настінний декор'=>'Wall decor','Малий декор'=>'Small decor','Декор для тераси'=>'Terrace decor','Для бізнесу'=>'For business','РЕАЛЬНІ ПРЕДМЕТИ В КАТАЛОЗІ'=>'REAL ITEMS IN THE CATALOG','Почніть із'=>'Start with','однієї деталі.'=>'one detail.','Увесь каталог'=>'Full catalog','До кошика'=>'Add to cart','ДЛЯ БУДИНКУ Й БІЗНЕСУ'=>'FOR HOME AND BUSINESS','Предмети'=>'Objects','краще звучать разом.'=>'work better together.','ПРИВАТНИЙ ПРОСТІР'=>'PRIVATE SPACE','Дім, сад або тераса'=>'Home, garden or terrace','Створити добірку'=>'Create a selection','ПРОФЕСІЙНИЙ ПРОЄКТ'=>'PROFESSIONAL PROJECT','Ресторан, готель чи шоурум'=>'Restaurant, hotel or showroom','Обговорити декор'=>'Discuss decor','СПІВПРАЦЯ'=>'COOPERATION','Для дизайнерів і архітекторів'=>'For designers and architects','Умови B2B'=>'B2B terms','Декор для тих,'=>'Decor for those','хто створює враження.'=>'who create impressions.','Для дизайнерів і бізнесу'=>'For designers and business','ПРО БРЕНД'=>'ABOUT THE BRAND','Декор не займає простір.'=>'Decor does not take up space.','Він його збирає.'=>'It brings it together.','Історія Ferreta'=>'The Ferreta story','ЖУРНАЛ'=>'JOURNAL','Читати'=>'Read','В наявності'=>'In stock','Немає в наявності'=>'Out of stock','Зберегти'=>'Save','Порівняти'=>'Compare','Категорія'=>'Category','Потрібна добірка для простору?'=>'Need a selection for your space?','ДОПОВНІТЬ КОМПОЗИЦІЮ'=>'COMPLETE THE COMPOSITION','Схожі предмети.'=>'Related objects.','Сортування'=>'Sort','КАТЕГОРІЯ НАПОВНЮЄТЬСЯ'=>'CATEGORY IS BEING CURATED','Ця добірка скоро з’явиться у каталозі.'=>'This selection will appear in the catalog soon.','Надіслати запит'=>'Send request','Обране'=>'Saved items','Порівняння'=>'Compare','Доставка й оплата'=>'Delivery and payment','Гарантія'=>'Warranty','Контакти'=>'Contacts','Поширені запитання'=>'FAQ']);}
add_action('template_redirect',function(){if(!is_admin()&&!wp_doing_ajax()&&ferreta_language()==='en')ob_start('ferreta_translate_markup');},0);
function ferreta_localize_english_markup(string $html):string{
  if(ferreta_language()!=='en')return $html;
  $html=strtr($html,['Дізнатися більше'=>'Learn more','Вхідна група'=>'Entrance area','Доріжка до тераси'=>'Path to the terrace','Садова алея'=>'Garden path','Проєктний підбір'=>'Project selection','Партнерська співпраця'=>'Partnership','Розкажіть про свій'=>'Tell us about your','Ім’я'=>'Name','Телефон'=>'Phone','Опишіть простір'=>'Describe the space','Погоджуюся на обробку персональних даних'=>'I agree to personal data processing','Усі світильники'=>'All objects','Для простору'=>'For spaces','Сервіс'=>'Service','Для професіоналів'=>'For professionals','Політика конфіденційності'=>'Privacy policy','Публічна оферта'=>'Public offer']);
  $html=strtr($html,['Каталог декору'=>'Decor catalog','Світло, меблі, лофт-об’єкти й малі деталі для дому, тераси та бізнесу.'=>'Lighting, furniture, loft objects and small details for home, terrace and business.','Усе'=>'All','Категорії каталогу'=>'Catalog categories','Пошук'=>'Search','Відкрити меню'=>'Open menu','Меню'=>'Menu','Комплекти'=>'Sets','Дизайнерам і бізнесу'=>'For designers and business','Розрахунок проєкту'=>'Project estimate','Реалізовані проєкти'=>'Completed projects','Декоративні автономні світильники для саду, тераси та архітектурних проєктів.'=>'Decorative autonomous lighting for gardens, terraces and architectural projects.','Великі справи на горизонті'=>'Big things are on the horizon','Щось велике готується! Наш магазин вже у процесі створення і незабаром буде запущений!'=>'Something big is coming. The store is being prepared and will launch soon.']);
  return preg_replace_callback("/\\bhref=([\"'])([^\"']+)\\1/",function(array $match):string{$url=html_entity_decode($match[2]);$home=parse_url(home_url('/'));$target=parse_url($url);if(isset($target['scheme'])&&(($target['host']??'')!==($home['host']??'')))return $match[0];if(str_starts_with($url,'#')||str_starts_with($url,'mailto:')||str_starts_with($url,'tel:')||str_contains($url,'/wp-content/')||str_contains($url,'/wp-admin/'))return $match[0];return 'href='.$match[1].esc_url(add_query_arg('lang','en',$url)).$match[1];},$html);
}
add_action('template_redirect',function(){if(!is_admin()&&!wp_doing_ajax()&&ferreta_language()==='en')ob_start('ferreta_localize_english_markup');},1);
add_action('after_setup_theme',function(){add_theme_support('woocommerce');add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',['search-form','gallery','caption']);register_nav_menus(['primary'=>'Primary menu','footer'=>'Footer menu']);});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('ferreta-reset',get_theme_file_uri('reset.css'),[],'1.1');wp_enqueue_style('ferreta',get_theme_file_uri('assets.css'),['ferreta-reset'],'1.3');wp_enqueue_style('ferreta-hub',get_theme_file_uri('hub.css'),['ferreta'],'1.0');wp_enqueue_style('ferreta-shop',get_theme_file_uri('shop.css'),['ferreta'],'1.1');wp_enqueue_style('ferreta-refinements',get_theme_file_uri('refinements.css'),['ferreta-shop'],'1.0');wp_enqueue_script('ferreta',get_theme_file_uri('assets.js'),[],'1.2',true);wp_enqueue_script('ferreta-refinements',get_theme_file_uri('refinements.js'),['ferreta'],'1.0',true);wp_localize_script('ferreta','Ferreta',['rest'=>rest_url('ferreta/v1/lead'),'cart'=>function_exists('wc_get_cart_url')?wc_get_cart_url():'/cart/','currency'=>'грн']);});
add_filter('woocommerce_show_page_title','__return_false');
add_filter('loop_shop_per_page',fn()=>24);
add_action('wp_head',function(){if(is_product()){global $product;if($product instanceof WC_Product){$schema=['@context'=>'https://schema.org','@type'=>'Product','name'=>$product->get_name(),'sku'=>$product->get_sku(),'offers'=>['@type'=>'Offer','priceCurrency'=>'UAH','price'=>$product->get_price(),'availability'=>$product->is_in_stock()?'https://schema.org/InStock':'https://schema.org/OutOfStock']];echo '<script type="application/ld+json">'.wp_json_encode($schema).'</script>';}}});
